"use client";

import Script from "next/script";

interface ClarityAnalyticsProps {
    clarityId?: string;
}

export default function ClarityAnalytics({ clarityId }: ClarityAnalyticsProps) {
    // Use the prop or fall back to environment variable
    const projectId = clarityId || process.env.NEXT_PUBLIC_CLARITY_PROJECT_ID;

    // Don't render if no project ID is available
    if (!projectId) {
        return null;
    }

    return (
        <Script
            id="microsoft-clarity"
            strategy="afterInteractive"
            dangerouslySetInnerHTML={{
                __html: `
          (function(c,l,a,r,i,t,y){
            c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};
            t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;
            y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);
          })(window, document, "clarity", "script", "${projectId}");
        `,
            }}
        />
    );
}
